package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.JdbcValueWrites;
import com.lianxibu.site.service.articles.ValueApplicationService;
import com.lianxibu.site.service.jobs.ResultApplicationService.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Actual original partial P1 and real member value SQL; downstream callback is controlled. */
class ValuePartialResultHandlerTest {
    SourcePartialPlanCoordinatorTest q;GenerationJdbcStoreTest db;SourcePartitionPlanner.Chunk part;Input input;
    ValueResultHandler handler;SourceDedupDependencyService deps;boolean fail;int downstream;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    @Test void ConstructorsAreLazyAndMissingOpaqueProofPortsCannotEnableCapture(){var values=mock(ValueApplicationService.class);@SuppressWarnings("unchecked") var snapshots=(java.util.function.BiFunction<String,String,String>)mock(java.util.function.BiFunction.class);var callback=mock(ValueResultHandler.Downstream.class);var deps=mock(SourceDedupDependencyService.class);var permits=mock(SourceDedupPartialDependencyPermitService.class);var tx=mock(org.springframework.transaction.PlatformTransactionManager.class);assertNotNull(new ValueResultHandler(values,snapshots,callback,deps,permits,tx));assertThrows(RuntimeException.class,()->new ValueResultHandler(values,snapshots,callback,deps,null,tx));verifyNoInteractions(values,snapshots,callback,deps,permits,tx);}
    void setup(int count)throws Exception{q=new SourcePartialPlanCoordinatorTest(){@Override GenerationJdbcStoreTest database(){return ValuePartialResultHandlerTest.this.database();}};q.setup(count,true);db=q.db;part=q.prepare(0).plan().chunks().getFirst();db.jdbc.execute("ALTER TABLE source_run_items ADD high_value INT");db.jdbc.execute("ALTER TABLE source_run_items ADD value_json "+(db.source instanceof org.h2.jdbcx.JdbcDataSource?"CLOB":"JSON"));input=FrozenApplicationContext.fromJson(CanonicalJson.parse(part.snapshotJson()).get(FrozenApplicationContext.FIELD)).input(part.rootId(),JdbcFrozenInputs.stableId("attempt",part.rootId()+":1"),part.inputHash(),0);deps=new SourceDedupDependencyService(q.q.a.observations,q.q.a.proven,q.q.a.service);handler=provider(q.q.a.service);}
    ValueResultHandler provider(SourceDedupPartialDependencyPermitService permits){return new ValueResultHandler(new ValueApplicationService(new JdbcValueWrites(db.source)),new JdbcFrozenInputs(db.source)::read,(i,r,v)->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());downstream++;if(fail)throw new IllegalStateException("fictional downstream failure");},new SourceDedupDependencyService(q.q.a.observations,q.q.a.proven,permits),permits,new DataSourceTransactionManager(db.source));}
    Validated result(){return ResultApplicationService.validate(input,ResultApplicationService.providerEnvelope(input,JdbcFrozenInputs.canonical(new SourceValueStageResultTest().payload(part))));}
    Applied apply(ValueResultHandler scope,Input original){var result=result();return db.writes.execute(new SharedWriteExecutor.ActionContext("fictional-partial-value-consumer",part.rootId(),part.inputHash()),k->null,c->scope.apply(original,result,new Current(1,part.inputHash(),0,null,true,false,null,null,original.attemptId(),true,null),false));}
    void empty(){assertEquals(0,db.jdbc.queryForObject("SELECT COUNT(*) FROM source_run_items WHERE value_json IS NOT NULL OR high_value IS NOT NULL",Integer.class));for(String id:part.itemIds())assertEquals(4,db.jdbc.queryForObject("SELECT revision FROM source_run_items WHERE id=?",Integer.class,id));}
    @Test void Actual201PartialFrameWritesOnlyItsOriginalMembersWithNativeEntityAndOrdinaryValue()throws Exception{setup(201);int calls=db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);var scope=handler.capture(input);assertEquals(new Applied(null,null),apply(scope,input));assertEquals(1,downstream);assertEquals(part.itemIds().size(),db.jdbc.queryForObject("SELECT COUNT(*) FROM source_run_items WHERE value_json IS NOT NULL",Integer.class));for(String id:part.itemIds()){var row=CanonicalJson.parse(db.jdbc.queryForObject("SELECT value_json FROM source_run_items WHERE id=?",String.class,id));assertEquals("member-value-v3",row.get("schema_version").asText());assertTrue(row.get("valuable").booleanValue());assertFalse(row.get("high_value").booleanValue());assertEquals("model",row.get("category").asText());assertEquals("news_tech",row.get("member_category").asText());assertEquals(db.jdbc.queryForObject("SELECT entity_id FROM source_run_items WHERE id=?",String.class,id),row.get("entity_id").asText());assertEquals(5,db.jdbc.queryForObject("SELECT revision FROM source_run_items WHERE id=?",Integer.class,id));}assertEquals(calls,db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertThrows(RuntimeException.class,()->apply(scope,input));assertEquals(1,downstream);}
    @Test void P1ChangeInsideWriterAndCurrentMemberIdentityCannotGrantAValueWrite()throws Exception{setup(101);String p1=q.q.a.f.plan.chunks().getLast().rootId();long revision=db.jdbc.queryForObject("SELECT revision FROM jobs WHERE id=?",Long.class,p1);var changed=spy(q.q.a.service);doAnswer(c->{db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",p1);return c.callRealMethod();}).when(changed).verify(any(),any());var changedScope=provider(changed).capture(input);assertThrows(RuntimeException.class,()->apply(changedScope,input));empty();assertEquals(revision,db.jdbc.queryForObject("SELECT revision FROM jobs WHERE id=?",Long.class,p1));var scope=handler.capture(input);String item=part.itemIds().getFirst(),entity=db.jdbc.queryForObject("SELECT entity_id FROM source_run_items WHERE id=?",String.class,item);db.jdbc.update("UPDATE source_run_items SET entity_id='fictional-swapped' WHERE id=?",item);var originalScope=scope;assertThrows(RuntimeException.class,()->apply(originalScope,input));empty();assertEquals(0,downstream);db.jdbc.update("UPDATE source_run_items SET entity_id=? WHERE id=?",entity,item);assertNotNull(apply(originalScope,input));}
    @Test void DownstreamFailureRollsBackEveryMemberAndTheSameOpaqueScopeRechecksTheWriter()throws Exception{setup(101);var scope=handler.capture(input);fail=true;assertThrows(RuntimeException.class,()->apply(scope,input));empty();fail=false;assertNotNull(apply(scope,input));assertEquals(part.itemIds().size(),db.jdbc.queryForObject("SELECT COUNT(*) FROM source_run_items WHERE value_json IS NOT NULL",Integer.class));}
    @Test void DefaultUncapturedDifferentOriginalInputAndWrongTransactionCannotUsePartialPermission()throws Exception{setup(101);assertThrows(RuntimeException.class,()->apply(handler,input));var legacy=new ValueResultHandler(new ValueApplicationService(new JdbcValueWrites(db.source)),new JdbcFrozenInputs(db.source)::read,(i,r,v)->{},deps);assertThrows(RuntimeException.class,()->apply(legacy,input));assertThrows(RuntimeException.class,()->legacy.capture(input));assertThrows(RuntimeException.class,()->q.q.h.f.readonly(()->handler.capture(input)));assertThrows(RuntimeException.class,()->q.q.h.f.p1.tx(()->handler.capture(input)));var scope=handler.capture(input);var other=FrozenApplicationContext.fromJson(CanonicalJson.parse(part.snapshotJson()).get(FrozenApplicationContext.FIELD)).input(part.rootId(),"fictional-other-attempt",part.inputHash(),0);assertThrows(RuntimeException.class,()->apply(scope,other));assertThrows(RuntimeException.class,()->scope.apply(input,result(),null,false));assertFalse(scope.toString().contains("Fictional"));empty();assertNotNull(apply(scope,input));}
}
